import re
from pathlib import Path
ROOT=Path('.')
CORPUS=Path('/tmp/cap-research')
DOCS=CORPUS/'docs'; SRC=CORPUS/'src'; HEAD=CORPUS/'src-head'
OFFICIAL=("https://capacitorjs.com/","https://github.com/ionic-team/","https://developer.apple.com/","https://developer.android.com/","https://developer.mozilla.org/","https://www.npmjs.com/package/@capacitor/","https://nodejs.org/")
TOKEN=re.compile(r'`((?:docs|src-head|src)/[A-Za-z0-9_./-]+(?::\d+(?:-\d+)?)?)`')
URL=re.compile(r'https?://[^\s)<>\];,]+')
PT=re.compile(r"(?i)\b(configura[cç][aã]o|verifica[cç][aã]o|implementa[cç][aã]o|integra[cç][aã]o|limita[cç][oõ]es|referência|documenta[cç][aã]o|análise|arquivo|código|seguran[cç]a|telemetria|usuário|páginas?|versão|obrigatóri[oa]|também|não|para|com|que|uma|deve|pode|apenas|porém|assim|ainda|porque|quando|enquanto|antes|depois|sobre|entre|através|por favor)\b|[áéíóúâêôãõç]")
def read_span(ref):
    path, span = (ref.rsplit(':',1)+[None])[:2] if ':' in ref else (ref,None)
    base = DOCS if path.startswith('docs/') else HEAD if path.startswith('src-head/') else SRC
    p = base/path.split('/',1)[1]
    if not p.exists(): return None, f'missing {path}'
    lines=p.read_text(errors='replace').splitlines()
    if span is None: return lines,None
    if '-' in span: a,b=map(int,span.split('-',1))
    else: a=b=int(span)
    if a<1 or b<a or b>len(lines): return None,f'bad range {ref}'
    return lines[a-1:b],None
files=['10-security.md','11-lint-and-code-quality.md','15-cordova-and-migration.md','17-updates-and-maintenance.md']
for name in files:
    probs=[]
    text=Path(name).read_text()
    size=len(text.encode())
    if not 6000<=size<=7600: probs.append(f'size {size}')
    if PT.search(re.sub(r'- https?://[^\n]+','',text)): probs.append('Portuguese leakage')
    lines=text.splitlines()
    sources=[l for l in lines if l.startswith('- http')]
    n=sum(1 for l in sources if any(l[2:].startswith(x) for x in OFFICIAL))
    if n<8: probs.append(f'only {n} official urls')
    for l in sources:
        for m in TOKEN.finditer(l):
            _,err=read_span(m.group(1));
            if err: probs.append(f'url token {err}')
    for m in TOKEN.finditer(text):
        _,err=read_span(m.group(1))
        if err: probs.append(f'token {err}')
    i=0; blocks=0
    while i<len(lines):
        if lines[i].startswith('```') and lines[i].strip()!='```':
            j=i+1; body=[]
            while j<len(lines) and not lines[j].startswith('```'):
                body.append(lines[j]); j+=1
            blocks+=1
            heads=[l.strip() for l in lines[max(0,i-3):i] if l.strip()]
            toks=[m.group(1) for l in heads for m in TOKEN.finditer(l) if ':' in m.group(1)]
            keyword=any(re.search(r'(?i)computed|output|calculation',l) for l in heads)
            if not toks and not keyword: probs.append(f'{i+1}: block without source')
            elif toks and len(body)<=25:
                src,err=read_span(toks[-1]); a=[x.strip() for x in body if x.strip()]; b=[x.strip() for x in src if x.strip()] if src else []
                if err: probs.append(f'{i+1}: {err}')
                elif a!=b: probs.append(f'{i+1}: block not literal vs {toks[-1]}')
            i=j+1
        else: i+=1
    print(name, 'bytes',size,'urls',n,'blocks',blocks,'PROBLEMS',probs if probs else 'NONE')
EOF)
