import re
from pathlib import Path
p=Path('/tmp/cap-research/notes/security-lint.md')
lines=p.read_text().splitlines()
rows=[l for l in lines if re.match(r'^\| [SL]\d\d \|',l)]
print('total rows',len(rows))
for prefix in ['S','L']:
    sub=[r for r in rows if re.match(rf'^\| {prefix}\d\d \|',r)]
    cells=[[c.strip() for c in r.strip('|').split('|')] for r in sub]
    ids=[c[0] for c in cells]
    statuses=[c[3] for c in cells]
    docs=sum(1 for s in statuses if s=='documented'); unv=sum(1 for s in statuses if s=='unverified')
    print(prefix,'rows',len(sub),'ids-ok',ids==[f'{prefix}{i:02d}' for i in range(1,21)],'col5',all(len(c)==5 for c in cells),'documented',docs,'unverified',unv,'cols-ok',all(c[1]==('security' if prefix=='S' else 'lint') for c in cells))
    for c in cells:
        ev=c[4]
        if ev=='unverified': continue
        path,span=ev.rsplit(':',1)
        base=Path('/tmp/cap-research/'+('docs' if path.startswith('docs/') else 'src-head' if path.startswith('src-head/') else 'src'))
        f=base/path.split('/',1)[1]
        if not f.exists(): print(' MISSING',ev)
        else:
            n=len(f.read_text(errors='replace').splitlines())
            if int(span)>n: print(' BAD LINE',ev,n)
EOF
